{
  "name": "salon-api",
  "scripts": {
    "test": "jest"
  },
  "dependencies": {
    "@nestjs/common": "^10.0.0",
    "@nestjs/core": "^10.0.0"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "typescript": "^5.4.0"
  }
}

import { Module } from '@nestjs/common';
import { BookingsModule } from './modules/bookings/bookings.module';
import { ServicesModule } from './modules/services/services.module';
import { UsersModule } from './modules/users/users.module';

@Module({ imports: [BookingsModule, ServicesModule, UsersModule] })
export class AppModule {}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

export async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000);
}

import { BookingsController } from './bookings.controller';

describe('BookingsController', () => {
  it('exists', () => expect(BookingsController).toBeDefined());
});

import { BookingsService } from './bookings.service';
import { CreateBookingDto } from './dto/create-booking.dto';

export class BookingsController {
  constructor(private readonly bookings: BookingsService) {}
  create(dto: CreateBookingDto) {
    return this.bookings.create(dto);
  }
}

import { Module } from '@nestjs/common';
import { BookingsController } from './bookings.controller';
import { BookingsService } from './bookings.service';

@Module({ controllers: [BookingsController], providers: [BookingsService] })
export class BookingsModule {}

import { Database } from '../../shared/database';

export class BookingsRepository {
  constructor(private readonly db: Database) {}
  insert(row: object) {
    return this.db.query(JSON.stringify(row));
  }
}

import { BookingsRepository } from './bookings.repository';
import { CreateBookingDto } from './dto/create-booking.dto';

export class BookingsService {
  constructor(private readonly repo: BookingsRepository) {}
  create(dto: CreateBookingDto) {
    return this.repo.insert(dto);
  }
}

export class CreateBookingDto {
  serviceId!: string;
  startsAt!: string;
}

import { ServicesService } from './services.service';

export class ServicesController {
  constructor(private readonly services: ServicesService) {}
}

import { Module } from '@nestjs/common';
import { ServicesController } from './services.controller';
import { ServicesService } from './services.service';

@Module({ controllers: [ServicesController], providers: [ServicesService] })
export class ServicesModule {}

import { ServicesService } from './services.service';

describe('ServicesService', () => {
  it('lists', () => expect(new ServicesService().list()).toEqual([]));
});

export class ServicesService {
  list() {
    return [];
  }
}

import { UsersService } from './users.service';

export class UsersController {
  constructor(private readonly users: UsersService) {}
}

import { Module } from '@nestjs/common';
import { UsersController } from './users.controller';
import { UsersService } from './users.service';

@Module({ controllers: [UsersController], providers: [UsersService] })
export class UsersModule {}

import { UsersService } from './users.service';

describe('UsersService', () => {
  it('exists', () => expect(UsersService).toBeDefined());
});

import { Database } from '../../shared/database';

export class UsersService {
  constructor(private readonly db: Database) {}
}

export class Database {
  query(sql: string) {
    return sql;
  }
}

{
  "compilerOptions": { "strict": true }
}
